// Save a post edit snapshot
if (!function_exists('save_post_edit')) {
function save_post_edit($post_id, $editor_id, $previous, $new) {
    // limit size
    $prev = mb_substr($previous ?? '', 0, 100 * 1024, 'UTF-8');
    $n = mb_substr($new ?? '', 0, 100 * 1024, 'UTF-8');

    static $postEditsColumns = null;
    if ($postEditsColumns === null) {
        $postEditsColumns = [];
        try {
            $stmt = query('SHOW COLUMNS FROM post_edits');
            foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $column) {
                $postEditsColumns[$column['Field']] = true;
            }
        } catch (Exception $e) {
            error_log('save_post_edit schema check failed: ' . $e->getMessage());
            return false;
        }
    }

    $columns = ['post_id', 'editor_id', 'previous_content', 'new_content'];
    $values = [$post_id, $editor_id, $prev, $n];

    if (!empty($postEditsColumns['original_content'])) {
        $columns[] = 'original_content';
        $values[] = $prev;
    }
    if (!empty($postEditsColumns['created_at'])) {
        $columns[] = 'created_at';
        $values[] = date('Y-m-d H:i:s');
    }

    $placeholders = implode(', ', array_fill(0, count($columns), '?'));
    $sql = 'INSERT INTO post_edits (' . implode(', ', $columns) . ') VALUES (' . $placeholders . ')';
    try {
        query($sql, $values);
        return true;
    } catch (Exception $e) {
        error_log('save_post_edit error: ' . $e->getMessage());
        return false;
    }
}
} // end guard: save_post_edit


