                    (SELECT COUNT(*) FROM likes WHERE post_id = p.id AND user_id = ?) as user_has_liked,
                    (SELECT COUNT(*) FROM posts WHERE parent_id = p.id AND deleted_at IS NULL) as comment_count
                FROM posts p 
                JOIN users u ON p.user_id = u.id 
                WHERE p.parent_id IS NULL AND p.deleted_at IS NULL AND u.deleted_at IS NULL 
                ORDER BY p.created_at DESC LIMIT ?
            ", [$viewer_id, $limit]);
            $rows = $stmt->fetchAll();
            $pids = array_column($rows, 'id');
            $pm = function_exists('batch_get_polls_for_posts') ? batch_get_polls_for_posts($pids) : [];
            $tm = function_exists('batch_get_tests_for_posts') ? batch_get_tests_for_posts($pids) : [];
            $cc = function_exists('batch_get_recursive_comment_counts') ? batch_get_recursive_comment_counts($pids) : [];
            foreach ($rows as &$r) {
                $r['poll'] = $pm[$r['id']] ?? null;
                $r['test'] = $tm[$r['id']] ?? null;
                if (isset($cc[$r['id']])) { $r['comment_count'] = $cc[$r['id']]; }
            }
            unset($r);
            return $rows;
        }
        // Show all users' posts (no approval/rookie visibility limit for user-specific feed)
        $stmt = query("
            SELECT p.*, u.username,
                (SELECT COUNT(*) FROM likes WHERE post_id = p.id) as like_count,
                (SELECT COUNT(*) FROM likes WHERE post_id = p.id AND user_id = ?) as user_has_liked,
                (SELECT COUNT(*) FROM posts WHERE parent_id = p.id AND deleted_at IS NULL) as comment_count
            FROM posts p 
            JOIN users u ON p.user_id = u.id 
            WHERE p.parent_id IS NULL AND p.deleted_at IS NULL AND u.deleted_at IS NULL
                AND (p.scheduled_at IS NULL OR p.scheduled_at <= NOW() OR p.user_id = ?)
            ORDER BY p.created_at DESC LIMIT ?
        ", [$viewer_id, $viewer_id, $limit]);
        $rows = $stmt->fetchAll();
        $pids = array_column($rows, 'id');
        $pm = function_exists('batch_get_polls_for_posts') ? batch_get_polls_for_posts($pids) : [];
        $tm = function_exists('batch_get_tests_for_posts') ? batch_get_tests_for_posts($pids) : [];
        $cc = function_exists('batch_get_recursive_comment_counts') ? batch_get_recursive_comment_counts($pids) : [];
        foreach ($rows as &$r) {
            $r['poll'] = $pm[$r['id']] ?? null;
            $r['test'] = $tm[$r['id']] ?? null;
            if (isset($cc[$r['id']])) { $r['comment_count'] = $cc[$r['id']]; }
        }
        unset($r);
        return $rows;
    }
    // Public view: show all users' top-level posts (no rookie limit)
    $stmt = query("
        SELECT p.*, u.username,
            (SELECT COUNT(*) FROM likes WHERE post_id = p.id) as like_count,
            0 as user_has_liked,
            (SELECT COUNT(*) FROM posts WHERE parent_id = p.id AND deleted_at IS NULL) as comment_count
        FROM posts p 
        JOIN users u ON p.user_id = u.id 
        WHERE p.parent_id IS NULL AND p.deleted_at IS NULL AND u.deleted_at IS NULL
            AND (p.scheduled_at IS NULL OR p.scheduled_at <= NOW())
        ORDER BY p.created_at DESC LIMIT ?
    ", [$limit]);
    $rows = $stmt->fetchAll();
    $pids = array_column($rows, 'id');
    $pm = function_exists('batch_get_polls_for_posts') ? batch_get_polls_for_posts($pids) : [];
    $tm = function_exists('batch_get_tests_for_posts') ? batch_get_tests_for_posts($pids) : [];
    $cc = function_exists('batch_get_recursive_comment_counts') ? batch_get_recursive_comment_counts($pids) : [];
    foreach ($rows as &$r) {
        $r['poll'] = $pm[$r['id']] ?? null;
        $r['test'] = $tm[$r['id']] ?? null;
        if (isset($cc[$r['id']])) { $r['comment_count'] = $cc[$r['id']]; }
    }
    unset($r);
    return $rows;
}
} // end guard: get_posts
 

