}
} // end guard: admin_resolve_report


// True when a post/reply still has non-deleted child replies.
if (!function_exists('post_has_active_child_replies')) {
function post_has_active_child_replies($post_id) {
    $stmt = query(
        "SELECT COUNT(*) FROM posts WHERE parent_id = ? AND deleted_at IS NULL",
        [(int)$post_id]
    );
    return ((int)$stmt->fetchColumn()) > 0;
}
} // end guard: post_has_active_child_replies


// Admin: delete a post (soft delete)
if (!function_exists('admin_delete_post')) {
function admin_delete_post($admin_id, $post_id) {
    // Fetch the post first so we can notify the author even after deletion
    $post = get_post($post_id);
    if (!$post) {
        return ['error' => 'not_found'];
    }

    // Soft-delete only. If this reply has child replies, keep the row as a
    // deleted placeholder so nested replies remain visible in the thread.
    query("UPDATE posts SET deleted_at = NOW() WHERE id = ?", [$post_id]);

    // If this was a reply, decrement parent replies_count
    if (!empty($post['parent_id'])) {
        query("UPDATE posts SET replies_count = GREATEST(0, replies_count - 1) WHERE id = ?", [$post['parent_id']]);
    }

    // Notify author if present
    create_notification($post['user_id'], 'report', $admin_id, $post_id);

    // mark any reports on this target as resolved (post or reply)
    query("UPDATE reports SET status = 'resolved' WHERE target_id = ? AND (target_type = 'post' OR target_type = 'reply')", [$post_id]);
    return true;
}
} // end guard: admin_delete_post


// User delete their own post
if (!function_exists('user_delete_post')) {
function user_delete_post($user_id, $post_id) {
    // Fetch the post to verify ownership
    $post = get_post($post_id);
    
    if (!$post || $post['user_id'] != $user_id) {
        error_log("user_delete_post failed: not_owner_or_missing user={$user_id} post={$post_id} post_owner=" . ($post['user_id'] ?? 'null'));
        return ['error' => 'not_owner']; // Not the owner
    }
    
    // Check if user is approved. Unapproved users are still allowed to delete their own posts.
    $user = get_user($user_id);
    if ($user && isset($user['is_approved']) && $user['is_approved'] == 0) {
        error_log("user_delete_post: unapproved user={$user_id} deleting own post={$post_id}");
    }

    // Special restriction: rookies may self-delete if allowed by config.
    if ($user && isset($user['role']) && $user['role'] === 'rookie' && !is_user_premium($user_id) && !ROOKIE_ALLOW_SELF_DELETE) {
        error_log("user_delete_post failed: rookie_restricted user={$user_id} role=rookie post={$post_id}");
        return ['error' => 'rookie_restricted'];
    }

    // Soft-delete only. Replies with children stay in the tree as deleted placeholders.
    query("UPDATE posts SET deleted_at = NOW() WHERE id = ?", [$post_id]);

    // If this was a reply, decrement parent replies_count
    if (!empty($post['parent_id'])) {
        query("UPDATE posts SET replies_count = GREATEST(0, replies_count - 1) WHERE id = ?", [$post['parent_id']]);
    }

    // Clean up any test association for this post.
    // If this was the last linked post for a test, remove the orphaned test and its data.
    // Skip cascading content removal when this reply still has active children —
    // the node remains as a deleted placeholder in the thread.
    $has_children = !empty($post['parent_id']) && post_has_active_child_replies($post_id);
    if (!$has_children) {
        $stmt = query("SELECT test_id FROM post_tests WHERE post_id = ? OR group_post_id = ? LIMIT 1", [$post_id, $post_id]);
        $linked_test_id = $stmt ? (int)$stmt->fetchColumn() : 0;
        query("DELETE FROM post_tests WHERE post_id = ? OR group_post_id = ?", [$post_id, $post_id]);

        if ($linked_test_id > 0) {
            $remaining = (int)query("SELECT COUNT(*) FROM post_tests WHERE test_id = ?", [$linked_test_id])->fetchColumn();
            if ($remaining === 0) {
                $attempt_rows = query("SELECT id FROM test_attempts WHERE test_id = ?", [$linked_test_id])->fetchAll(PDO::FETCH_COLUMN);
                if (!empty($attempt_rows)) {
                    $placeholders = implode(',', array_fill(0, count($attempt_rows), '?'));
                    query("DELETE FROM test_answers WHERE attempt_id IN ($placeholders)", $attempt_rows);
                }
                query("DELETE FROM test_attempts WHERE test_id = ?", [$linked_test_id]);
                query("DELETE FROM question_options WHERE question_id IN (SELECT id FROM test_questions WHERE test_id = ?)", [$linked_test_id]);
                query("DELETE FROM test_questions WHERE test_id = ?", [$linked_test_id]);
                query("DELETE FROM test_thresholds WHERE test_id = ?", [$linked_test_id]);
                query("DELETE FROM tests WHERE id = ?", [$linked_test_id]);
            }
        }
    }
    
    return true;
}
} // end guard: user_delete_post


