        $sql .= " WHERE (r.status IS NULL OR r.status = 'open')";
    } elseif ($status === 'resolved') {
        $sql .= " WHERE r.status = 'resolved'";
    }

    $sql .= " ORDER BY r.created_at DESC LIMIT ?";
    $params[] = $limit;

    $stmt = query($sql, $params);
