// Like/unlike a post
if (!function_exists('toggle_like')) {
function toggle_like($user_id, $post_id, $reaction = '🔥') {
    $pdo = db_connect();

    try {
        $pdo->beginTransaction();

        // Lock existing like row for this user/post pair to avoid race condition
        $lockStmt = $pdo->prepare("SELECT id FROM likes WHERE user_id = ? AND post_id = ? FOR UPDATE");
        $lockStmt->execute([$user_id, $post_id]);
        $existing = $lockStmt->fetch(PDO::FETCH_ASSOC);

        if ($existing) {
            query("DELETE FROM likes WHERE user_id = ? AND post_id = ?", [$user_id, $post_id]);
            query("UPDATE posts SET likes_count = GREATEST(0, likes_count - 1) WHERE id = ?", [$post_id]);
            $pdo->commit();
            return false;
        }

        query("INSERT INTO likes (user_id, post_id, reaction) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE reaction = VALUES(reaction)", [$user_id, $post_id, $reaction]);
        query("UPDATE posts SET likes_count = likes_count + 1 WHERE id = ?", [$post_id]);

        $post = get_post($post_id);
        if ($post && $post['user_id'] != $user_id) {
            create_notification($post['user_id'], 'like', $user_id, $post_id);
        }

        maybe_sync_badges_after_like($post_id);

        $pdo->commit();
        return true;
    } catch (Throwable $e) {
        if ($pdo->inTransaction()) {
            $pdo->rollBack();
        }
        error_log('toggle_like error: ' . $e->getMessage());
        return false;
    }
}
} // end guard: toggle_like


// Reconcile likes_count and replies_count for a post or all posts
if (!function_exists('reconcile_post_counters')) {
function reconcile_post_counters($post_id = null) {
    $pdo = db_connect();

    if ($post_id !== null) {
        try {
            $pdo->beginTransaction();
            $likes = query("SELECT COUNT(*) AS c FROM likes WHERE post_id = ?", [$post_id])->fetch()['c'] ?? 0;
            $replies = query("SELECT COUNT(*) AS c FROM posts WHERE parent_id = ? AND deleted_at IS NULL", [$post_id])->fetch()['c'] ?? 0;
            query("UPDATE posts SET likes_count = ?, replies_count = ? WHERE id = ?", [$likes, $replies, $post_id]);
            $pdo->commit();
            return true;
        } catch (Throwable $e) {
            if ($pdo->inTransaction()) {
                $pdo->rollBack();
            }
            error_log('reconcile_post_counters error: ' . $e->getMessage());
            return false;
        }
    }

    $limit = 500;
    $offset = 0;
    while (true) {
        $posts = query("SELECT id FROM posts WHERE parent_id IS NULL AND deleted_at IS NULL ORDER BY id ASC LIMIT ? OFFSET ?", [$limit, $offset])->fetchAll(PDO::FETCH_ASSOC);
        if (empty($posts)) {
            break;
        }
        foreach ($posts as $row) {
            reconcile_post_counters($row['id']);
        }
        $offset += $limit;
    }

    return true;
}
}

