// Get mentioned users in a text. Returns array of user rows (id, username, ...)
if (!function_exists('get_mentions')) {
function get_mentions($text) {
    $users = [];
    $seen_ids = [];
    if (preg_match_all('/@([\p{L}\p{N}_-]+(?: [\p{L}\p{N}_-]+)?)/u', $text, $matches)) {
        $names = array_unique($matches[1]);
        foreach ($names as $name) {
            $name = trim($name);
            $u = get_user_by_username($name);
            if (!$u) {
                // Try slug-based lookup for names like @hatasiz-cool
                $u = get_user_by_slug($name);
            }
            // If the two-word match didn't resolve to a user, fall back to just
            // the first word — handles "@username some text" where the greedy
            // optional second-word group captured a following plain word.
            if (!$u && strpos($name, ' ') !== false) {
                $first_word = explode(' ', $name)[0];
                $u = get_user_by_username($first_word);
                if (!$u) {
                    $u = get_user_by_slug($first_word);
                }
            }
            if ($u && !in_array($u['id'], $seen_ids)) {
                $seen_ids[] = $u['id'];
                $users[] = $u;
            }
        }
    }
    return $users;
}
} // end guard: get_mentions


