if (!function_exists('set_last_groups_page_viewed_at')) {
function set_last_groups_page_viewed_at($user_id, $timestamp = null) {
    if (empty($user_id)) {
        return false;
    }
    if ($timestamp === null) {
        $timestamp = date('Y-m-d H:i:s');
    }
    $_SESSION['last_groups_page_viewed_at'] = $timestamp;

    try {
