if (!function_exists('get_new_group_posts_count')) {
function get_new_group_posts_count($user_id) {
    if (empty($user_id)) {
        return 0;
    }

    $groupViewsEnabled = false;
    try {
        $tableStmt = query("SHOW TABLES LIKE 'group_views'");
        if ($tableStmt && $tableStmt->rowCount() > 0) {
            $groupViewsEnabled = true;
        }
    } catch (Exception $_) {
        $groupViewsEnabled = false;
    }

    try {
        if ($groupViewsEnabled) {
            $stmt = query(
                "SELECT COUNT(DISTINCT gp.group_id) AS c
                FROM group_posts gp
                JOIN group_members gm ON gp.group_id = gm.group_id
                LEFT JOIN group_views gv ON gv.group_id = gp.group_id AND gv.user_id = gm.user_id
                WHERE gm.user_id = ?
                  AND gm.role IN ('owner', 'moderator', 'member', 'admin')
                  AND gp.created_at > COALESCE(gv.viewed_at, gm.joined_at, '1970-01-01 00:00:00')",
                [$user_id]
            );
        } else {
            $stmt = query(
                "SELECT COUNT(DISTINCT gp.group_id) AS c
                FROM group_posts gp
                JOIN group_members gm ON gp.group_id = gm.group_id
                WHERE gm.user_id = ?
                  AND gm.role IN ('owner', 'moderator', 'member', 'admin')
                  AND gp.created_at > COALESCE(gm.joined_at, '1970-01-01 00:00:00')",
                [$user_id]
            );
        }
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        return (int)($row['c'] ?? 0);
    } catch (Exception $_) {
        return 0;
    }
}
} // end guard: get_new_group_posts_count


