// Format timestamp
if (!function_exists('format_time')) {
function format_time($timestamp) {
    $tzName = date_default_timezone_get() ?: 'Europe/Istanbul';
    $tz = new DateTimeZone($tzName);

    try {
        $dt = new DateTimeImmutable($timestamp, $tz);
    } catch (Exception $e) {
        $ts = @strtotime($timestamp);
        if ($ts === false) {
            $ts = time();
        }
        $dt = (new DateTimeImmutable())->setTimestamp($ts)->setTimezone($tz);
    }

    $now = new DateTimeImmutable('now', $tz);
    $diff = $now->getTimestamp() - $dt->getTimestamp();

    if ($diff < 60) {
        return 'az önce';
    } elseif ($diff < 3600) {
        return floor($diff / 60) . ' dakika önce';
    } elseif ($diff < 86400) {
        return floor($diff / 3600) . ' saat önce';
    } elseif ($diff < 604800) {
        return floor($diff / 86400) . ' gün önce';
    } else {
        return $dt->format('d.m.Y H:i');
    }
}
} // end guard: format_time


// Send an email, preferring SMTP via PHPMailer (if configured) and falling back to mail()
if (!function_exists('send_email')) {
function send_email($to, $subject, $body) {
    $from_email = defined('MAIL_FROM_EMAIL') ? MAIL_FROM_EMAIL : 'no-reply@example.com';
    $from_name = defined('MAIL_FROM_NAME') ? MAIL_FROM_NAME : SITE_NAME;

    // Resolve SMTP settings from constants (config.php) or env vars
    $smtp_host = defined('SMTP_HOST') ? SMTP_HOST : getenv('SMTP_HOST');
    $smtp_port = defined('SMTP_PORT') ? SMTP_PORT : intval(getenv('SMTP_PORT') ?: 587);
    $smtp_user = defined('SMTP_USER') ? SMTP_USER : getenv('SMTP_USER');
    $smtp_pass = defined('SMTP_PASS') ? SMTP_PASS : getenv('SMTP_PASS');
    $smtp_secure = defined('SMTP_SECURE') ? SMTP_SECURE : (getenv('SMTP_SECURE') ?: 'tls');

    // Debug: log which email transport is being used
    error_log(sprintf('[MAIL] send_email(%s) smtp_host=%s smtp_user=%s smtp_pass=%s phpmailer=%s',
        $to,
        $smtp_host ?: 'NONE',
        $smtp_user ? 'SET' : 'NONE',
        $smtp_pass ? 'SET' : 'NONE',
        class_exists('PHPMailer\PHPMailer\PHPMailer') ? 'yes' : 'no'
    ));

    // Load PHPMailer if available (for SMTP sending)
    $phpmailer_dir = __DIR__ . '/../vendor/phpmailer/src';
    if (is_dir($phpmailer_dir)) {
        require_once $phpmailer_dir . '/Exception.php';
        require_once $phpmailer_dir . '/PHPMailer.php';
        require_once $phpmailer_dir . '/SMTP.php';
    } else {
        error_log('[MAIL] PHPMailer directory not found: ' . $phpmailer_dir);
    }

    $smtpConfigured = !empty($smtp_host) && !empty($smtp_user) && !empty($smtp_pass);
    // If SMTP is fully configured and PHPMailer is available, use it.
    if ($smtpConfigured && class_exists('PHPMailer\PHPMailer\PHPMailer')) {
        error_log('[MAIL] Using PHPMailer via SMTP host ' . $smtp_host . ' for ' . $to);
        try {
            $mail = new PHPMailer\PHPMailer\PHPMailer(true);
            $mail->isSMTP();
            $mail->Host = $smtp_host;
            $mail->Port = $smtp_port;
            $mail->SMTPAuth = true;
            $mail->Username = $smtp_user;
            $mail->Password = $smtp_pass;
            $mail->SMTPSecure = $smtp_secure;
            $mail->CharSet = 'UTF-8';
            // Use the authenticated SMTP user as the envelope sender to avoid relay/alias rejection.
            // Keep the site 'From' in Reply-To so replies go to the configured address.
            $from_address = !empty($smtp_user) ? $smtp_user : $from_email;
            $mail->setFrom($from_address, $from_name);
            if ($from_address !== $from_email && !empty($from_email)) {
                $mail->addReplyTo($from_email, $from_name);
            }
            $mail->addAddress($to);
            $mail->Subject = $subject;
            $mail->isHTML(true);
            $mail->Body = function_exists('email_body_to_html') ? email_body_to_html($body) : nl2br(htmlspecialchars($body));
            $mail->AltBody = $body;
            if ($mail->send()) {
                error_log('[MAIL] PHPMailer send ok for ' . $to);
                @file_put_contents('/tmp/mail_debug.log', date('c') . " PHPMailer ok to $to\n", FILE_APPEND);
                return true;
            }
            error_log('[MAIL] PHPMailer send failed for ' . $to);
            @file_put_contents('/tmp/mail_debug.log', date('c') . " PHPMailer failed to $to\n", FILE_APPEND);
        } catch (Exception $e) {
            error_log('[MAIL] PHPMailer error: ' . $e->getMessage());
            @file_put_contents('/tmp/mail_debug.log', date('c') . " PHPMailer error to $to: " . $e->getMessage() . "\n", FILE_APPEND);
        }

        // Do not fall back to mail() when SMTP is configured; prefer explicit failure for debugging.
        return false;
    }

    if (!empty($smtp_host) && !$smtpConfigured) {
        error_log('[MAIL] Incomplete SMTP settings, falling back to mail() for ' . $to);
        @file_put_contents('/tmp/mail_debug.log', date('c') . " Incomplete SMTP, fallback mail() for $to\n", FILE_APPEND);
    } else {
        error_log('[MAIL] Falling back to mail() for ' . $to);
        @file_put_contents('/tmp/mail_debug.log', date('c') . " Fallback mail() for $to\n", FILE_APPEND);
    }
    // Fallback to simple mail() if PHPMailer not available or SMTP not configured
    $headers = "From: " . $from_name . " <" . $from_email . ">\r\n";
    $headers .= "MIME-Version: 1.0\r\n";
    $headers .= "Content-Type: text/html; charset=UTF-8\r\n";
    if (defined('MAIL_ENABLED') && MAIL_ENABLED) {
        $html_body = function_exists('email_body_to_html') ? email_body_to_html($body) : nl2br(htmlspecialchars($body));
        $sent = mail($to, $subject, $html_body, $headers);
        @file_put_contents('/tmp/mail_debug.log', date('c') . " mail() to $to " . ($sent ? 'OK' : 'FAILED') . "\n", FILE_APPEND);
        return $sent;
    } else {
        error_log('[MAIL] Mail disabled (MAIL_ENABLED=false) - not sending to ' . $to);
        @file_put_contents('/tmp/mail_debug.log', date('c') . " mail disabled for $to\n", FILE_APPEND);
        return false;
    }
}
} // end guard: send_email

if (!function_exists('ensure_bulk_optin_tables')) {
function ensure_bulk_optin_tables() {
    try {
        query("CREATE TABLE IF NOT EXISTS bulk_optin_jobs (
            id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            title VARCHAR(191) NOT NULL,
            subject VARCHAR(255) NOT NULL,
            body TEXT NOT NULL,
            created_by INT NOT NULL,
            status ENUM('draft','queued','sending','completed','failed') NOT NULL DEFAULT 'draft',
            total INT NOT NULL DEFAULT 0,
            sent_count INT NOT NULL DEFAULT 0,
            failed_count INT NOT NULL DEFAULT 0,
            created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (id)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

        query("CREATE TABLE IF NOT EXISTS bulk_optin_emails (
            id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            job_id BIGINT UNSIGNED NOT NULL,
            name VARCHAR(191) DEFAULT NULL,
            email VARCHAR(191) NOT NULL,
            source VARCHAR(191) DEFAULT NULL,
            status ENUM('pending','sent','failed','skipped','opted_out') NOT NULL DEFAULT 'pending',
            attempts INT NOT NULL DEFAULT 0,
            sent_at DATETIME DEFAULT NULL,
            last_error TEXT DEFAULT NULL,
            created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            UNIQUE KEY uniq_job_email (job_id, email),
            INDEX idx_status (status),
            INDEX idx_job_id (job_id)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

        query("CREATE TABLE IF NOT EXISTS bulk_optin_optouts (
            id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            email VARCHAR(191) NOT NULL,
            reason VARCHAR(255) DEFAULT NULL,
            created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            UNIQUE KEY uniq_email (email)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

        query("CREATE TABLE IF NOT EXISTS bulk_optout_tokens (
            id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            email VARCHAR(191) NOT NULL,
            token CHAR(64) NOT NULL,
            used TINYINT(1) NOT NULL DEFAULT 0,
            created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
            used_at DATETIME DEFAULT NULL,
            PRIMARY KEY (id),
            UNIQUE KEY uniq_token (token),
            INDEX idx_email (email)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    } catch (Exception $e) {
        error_log('[BULK_OPTIN] ensure tables error: ' . $e->getMessage());
    }
}
}





if (!function_exists('parse_bulk_optin_xml')) {
function parse_bulk_optin_xml(string $xml): array {
    $result = ['rows' => [], 'errors' => []];
    if (trim($xml) === '') {
        $result['errors'][] = 'XML içeriği boş.';
        return $result;
    }

    libxml_use_internal_errors(true);
    $parsed = simplexml_load_string($xml);
    if ($parsed === false) {
        foreach (libxml_get_errors() as $err) {
            $result['errors'][] = trim($err->message);
        }
        libxml_clear_errors();
        return $result;
    }

    $emails = [];
    foreach ($parsed->contact as $contact) {
        $name = trim((string)$contact->name);
        if ($name === '') {
            $name = trim((string)$contact->isim);
        }
        $email = trim((string)$contact->email);
        $source = trim((string)$contact->source);
        if ($source === '') {
            $source = trim((string)$contact->kaynak);
        }
        if ($email === '') {
            $result['errors'][] = 'E-posta adresi eksik bir satır bulundu.';
            continue;
        }
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            $result['errors'][] = 'Geçersiz e-posta: ' . htmlspecialchars($email);
            continue;
        }
        $key = mb_strtolower($email);
        if (isset($emails[$key])) {
            continue;
        }
        $emails[$key] = [
            'name' => $name ?: null,
            'email' => $email,
            'source' => $source ?: null,
        ];
    }

    $result['rows'] = array_values($emails);
    return $result;
}
}

if (!function_exists('parse_bulk_optin_csv')) {
function parse_bulk_optin_csv(string $content): array {
    $result = ['rows' => [], 'errors' => []];
    $content = str_replace(["\r\n", "\r"], "\n", $content);
    $lines = array_filter(array_map('trim', explode("\n", $content)), fn($line) => $line !== '');
    if (empty($lines)) {
        $result['errors'][] = 'CSV içeriği boş.';
        return $result;
    }

    $headers = null;
    $rows = [];
    foreach ($lines as $index => $line) {
        $fields = str_getcsv($line);
        if ($index === 0) {
            $rawHeaders = array_map(fn($v) => mb_strtolower(trim($v)), $fields);
            $normalizedHeaders = array_map(function ($column) {
                return match ($column) {
                    'email' => 'email',
                    'name', 'isim' => 'name',
                    'source', 'kaynak' => 'source',
                    default => $column,
                };
            }, $rawHeaders);
            if (in_array('email', $normalizedHeaders, true)) {
                $headers = $normalizedHeaders;
                continue;
            }
        }

        if ($headers !== null) {
            $row = [];
            foreach ($headers as $key => $column) {
                $row[$column] = isset($fields[$key]) ? trim($fields[$key]) : '';
            }
            $rows[] = $row;
        } else {
            if (count($fields) === 1) {
                $rows[] = ['email' => trim($fields[0])];
            } elseif (count($fields) === 2) {
                $rows[] = ['name' => trim($fields[0]), 'email' => trim($fields[1])];
            } else {
                $rows[] = ['name' => trim($fields[0]), 'email' => trim($fields[1] ?? ''), 'source' => trim($fields[2] ?? '')];
            }
        }
    }

    $emails = [];
    foreach ($rows as $rowIndex => $row) {
        $name = trim($row['name'] ?? '');
        $email = trim($row['email'] ?? '');
        $source = trim($row['source'] ?? '');

        if ($email === '') {
            $result['errors'][] = sprintf('CSV satırı %d: e-posta adresi eksik.', $rowIndex + 1 + ($headers ? 1 : 0));
            continue;
        }
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            $result['errors'][] = sprintf('CSV satırı %d: geçersiz e-posta adresi (%s).', $rowIndex + 1 + ($headers ? 1 : 0), htmlspecialchars($email));
            continue;
        }

        $key = mb_strtolower($email);
        if (isset($emails[$key])) {
            continue;
        }
        $emails[$key] = [
            'name' => $name ?: null,
            'email' => $email,
            'source' => $source ?: null,
        ];
    }

    $result['rows'] = array_values($emails);
    return $result;
}
}

if (!function_exists('parse_bulk_optin_upload_file')) {
function parse_bulk_optin_upload_file(array $file): array {
    $result = ['rows' => [], 'errors' => []];
    if (!isset($file['error']) || $file['error'] !== UPLOAD_ERR_OK) {
        if (isset($file['error'])) {
            switch ($file['error']) {
                case UPLOAD_ERR_INI_SIZE:
                case UPLOAD_ERR_FORM_SIZE:
                    $result['errors'][] = 'Dosya çok büyük.';
                    break;
                case UPLOAD_ERR_NO_FILE:
                    $result['errors'][] = 'CSV veya Excel dosyası seçilmedi.';
                    break;
                case UPLOAD_ERR_PARTIAL:
                    $result['errors'][] = 'Dosya yalnızca kısmen yüklendi.';
                    break;
                case UPLOAD_ERR_NO_TMP_DIR:
                    $result['errors'][] = 'Sunucuda geçici yükleme dizini bulunamadı.';
                    break;
                case UPLOAD_ERR_CANT_WRITE:
                    $result['errors'][] = 'Dosya diske yazılamadı.';
                    break;
                case UPLOAD_ERR_EXTENSION:
                    $result['errors'][] = 'Dosya yüklemesi PHP uzantısı tarafından durduruldu.';
                    break;
                default:
                    $result['errors'][] = 'Dosya yükleme hatası (' . intval($file['error']) . ').';
                    break;
            }
        } else {
            $result['errors'][] = 'Dosya yükleme bilgisi eksik.';
        }
        return $result;
    }

    $name = $file['name'] ?? '';
    $extension = mb_strtolower(pathinfo($name, PATHINFO_EXTENSION));
    if (!in_array($extension, ['csv', 'xls', 'xlsx'], true)) {
        $result['errors'][] = 'Sadece CSV veya Excel (.xls/.xlsx) dosyaları kabul edilir.';
        return $result;
    }

    if ($file['size'] > 250 * 1024) {
        $result['errors'][] = 'Dosya boyutu 250 KB sınırını aşıyor.';
        return $result;
    }

    $content = file_get_contents($file['tmp_name']);
    if ($content === false) {
        $result['errors'][] = 'Dosya okunamadı.';
        return $result;
    }

    if ($extension === 'csv') {
        return parse_bulk_optin_csv($content);
    }

    if (class_exists('PhpOffice\PhpSpreadsheet\IOFactory')) {
        try {
            $spreadsheet = PhpOffice\PhpSpreadsheet\IOFactory::load($file['tmp_name']);
            $sheet = $spreadsheet->getActiveSheet();
            $rows = [];
            foreach ($sheet->getRowIterator() as $rowIndex => $row) {
                $cellIterator = $row->getCellIterator();
                $cellIterator->setIterateOnlyExistingCells(false);
                $rowValues = [];
                foreach ($cellIterator as $cell) {
                    $rowValues[] = trim((string)$cell->getValue());
                }
                $rows[] = $rowValues;
            }
            $csvData = '';
            foreach ($rows as $row) {
                $csvData .= implode(',', array_map(function($cell) { return '"' . str_replace('"', '""', $cell) . '"'; }, $row)) . "\n";
            }
            return parse_bulk_optin_csv($csvData);
        } catch (Throwable $e) {
            $result['errors'][] = 'Excel dosyası işlenirken hata oluştu.';
            return $result;
        }
    }

    $result['errors'][] = 'Excel yüklemesi desteklenmiyor; lütfen CSV kullanın.';
    return $result;
}
}

