if (!function_exists('create_bulk_optout_token')) {
function create_bulk_optout_token(string $email): string {
    $token = bin2hex(random_bytes(32));
    $pdo = db_connect();
    $stmt = $pdo->prepare("INSERT INTO bulk_optout_tokens (email, token) VALUES (?, ?) ON DUPLICATE KEY UPDATE token = VALUES(token), used = 0, created_at = NOW()");
    $stmt->execute([$email, $token]);
    return $token;
}
}

if (!function_exists('validate_bulk_optout_token')) {
function validate_bulk_optout_token(string $token) {
    $pdo = db_connect();
    $stmt = $pdo->prepare("SELECT email, used FROM bulk_optout_tokens WHERE token = ? LIMIT 1");
    $stmt->execute([$token]);
    $row = $stmt->fetch(PDO::FETCH_ASSOC);
    if (!$row || $row['used']) {
        return false;
    }
    return $row['email'];
}
}

