if (!function_exists('queue_bulk_optin_emails')) {
function queue_bulk_optin_emails(int $job_id, array $rows) {
    $pdo = db_connect();
    $stmt = $pdo->prepare("INSERT IGNORE INTO bulk_optin_emails (job_id, name, email, source, status, created_at) VALUES (?, ?, ?, ?, 'pending', NOW())");
    $inserted = 0;
    foreach ($rows as $row) {
        if (empty($row['email'])) {
            continue;
        }
        if (is_bulk_opted_out($row['email'])) {
            continue;
        }
        $stmt->execute([$job_id, $row['name'] ?? null, $row['email'], $row['source'] ?? null]);
        $inserted += $stmt->rowCount();
    }
    return $inserted;
}
}

if (!function_exists('process_bulk_optin_queue')) {
function process_bulk_optin_queue(array $options = []): array {
    ensure_bulk_optin_tables();
    $pdo = db_connect();
    $defaultLockFile = __DIR__ . '/../tmp/mevoptin.lock';
    $fallbackLockFile = sys_get_temp_dir() . '/mevoptin.lock';
    $lockFile = $options['lock_file'] ?? $defaultLockFile;
    $lockPaths = array_unique([$lockFile, $defaultLockFile, $fallbackLockFile]);
    $fp = null;
    $lockError = null;

    foreach ($lockPaths as $path) {
        $lockDir = dirname($path);
        if (!is_dir($lockDir) && !mkdir($lockDir, 0775, true) && !is_dir($lockDir)) {
            $lockError = 'Kilit dizini oluşturulamadı: ' . $lockDir;
            continue;
        }
        if (file_exists($path)) {
            @chmod($path, 0666);
        }
        @file_put_contents('/tmp/bulk_optin_worker.log', date('c') . " trying lock path: $path\n", FILE_APPEND);
        $fp = @fopen($path, 'c');
        if ($fp) {
            @chmod($path, 0666);
            @file_put_contents('/tmp/bulk_optin_worker.log', date('c') . " lock opened: $path\n", FILE_APPEND);
            break;
        }
        $error = error_get_last();
        $lockError = isset($error['message']) ? 'Kilit dosyası açılamadı: ' . $error['message'] : 'Kilit dosyası açılamadı.';
    }

    if (!$fp) {
        return ['ok' => false, 'message' => $lockError ?: 'Kilit dosyası açılamadı.'];
    }

    $maxLockAttempts = intval($options['lock_attempts'] ?? 10);
    $lockWaitUsec = intval($options['lock_wait_usec'] ?? 200000);
    $locked = false;
    for ($attempt = 0; $attempt < $maxLockAttempts; $attempt++) {
        if (flock($fp, LOCK_EX | LOCK_NB)) {
            $locked = true;
            break;
        }
        usleep($lockWaitUsec);
    }
    if (!$locked) {
        // Attempt stale-lock recovery: if the lockfile is older than configured threshold,
        // remove it and retry acquiring the lock. This helps when a previous worker
        // exited without releasing the lock.
        $staleSeconds = intval($options['stale_lock_seconds'] ?? intval(getenv('BULK_OPTIN_STALE_LOCK_SECONDS') ?: 300));
        $staleHandled = false;
        if ($staleSeconds > 0) {
            clearstatcache(true, $path);
            $mtime = @filemtime($path);
            if ($mtime !== false && (time() - $mtime) > $staleSeconds) {
                @file_put_contents('/tmp/bulk_optin_worker.log', date('c') . " stale lock detected: $path mtime=" . ($mtime ?: '0') . " - removing\n", FILE_APPEND);
                // try to release and remove stale lock
                @flock($fp, LOCK_UN);
                @fclose($fp);
                @unlink($path);
                // try to reopen and lock once more
                $fp = @fopen($path, 'c');
                if ($fp) {
                    @chmod($path, 0666);
                    for ($attempt = 0; $attempt < $maxLockAttempts; $attempt++) {
                        if (flock($fp, LOCK_EX | LOCK_NB)) {
                            $locked = true;
                            $staleHandled = true;
                            break;
                        }
                        usleep($lockWaitUsec);
                    }
                    if (!$locked) {
                        @fclose($fp);
                    }
                }
            }
        }

        if (!$locked) {
            return ['ok' => false, 'message' => 'Worker zaten çalışıyor veya kilit alınamıyor.'];
        }
        if ($staleHandled) {
            @file_put_contents('/tmp/bulk_optin_worker.log', date('c') . " stale lock cleared and lock acquired: $path\n", FILE_APPEND);
        }
    }

    $batchSize = intval($options['batch_size'] ?? intval(getenv('BULK_OPTIN_BATCH_SIZE') ?: 20));
    $maxAttempts = intval($options['max_attempts'] ?? intval(getenv('BULK_OPTIN_MAX_ATTEMPTS') ?: 5));
    $retryDelay = intval($options['retry_delay'] ?? intval(getenv('BULK_OPTIN_RETRY_DELAY') ?: 600));
    $mailRate = intval($options['rate_per_min'] ?? intval(getenv('BULK_OPTIN_RATE_PER_MIN') ?: 20));
    $sleepUsec = intval((60 / max(1, $mailRate)) * 1000000);

    try {
        $stmt = $pdo->prepare("SELECT be.*, bj.subject, bj.body, bj.status AS job_status
              FROM bulk_optin_emails be
              JOIN bulk_optin_jobs bj ON be.job_id = bj.id
              WHERE be.status = 'pending' AND be.attempts < ? AND (bj.status IN ('queued','sending'))
              ORDER BY be.id ASC LIMIT ?");
        $stmt->execute([$maxAttempts, $batchSize]);
        $jobs = $stmt->fetchAll(PDO::FETCH_ASSOC);

        foreach ($jobs as $job) {
            $email = $job['email'];
            if (is_bulk_opted_out($email)) {
                $update = $pdo->prepare("UPDATE bulk_optin_emails SET status = 'opted_out' WHERE id = ?");
                $update->execute([$job['id']]);
                continue;
            }

            $data = [
                'name' => $job['name'] ?: 'Sayın İlgili',
                'source' => $job['source'] ?: 'tanıdığınız bir kaynaktan',
                'email' => $email,
                'register_link' => full_url(BASE_PATH . '/kayit'),
                'opt_out_link' => get_bulk_optout_link($email),
            ];

            $subject = render_bulk_optin_template($job['subject'], $data);
            $body = render_bulk_optin_template($job['body'], $data);

            $sendOk = false;
            try {
                $sendOk = send_email($email, $subject, $body);
            } catch (Throwable $e) {
                $error = $e->getMessage();
            }

            if ($sendOk) {
                $update = $pdo->prepare("UPDATE bulk_optin_emails SET status = 'sent', attempts = attempts + 1, sent_at = NOW(), last_error = NULL WHERE id = ?");
                $update->execute([$job['id']]);
            } else {
                $error = $error ?? 'unknown error';
                $status = $job['attempts'] + 1 >= $maxAttempts ? 'failed' : 'pending';
                $update = $pdo->prepare("UPDATE bulk_optin_emails SET status = ?, attempts = attempts + 1, last_error = ?, sent_at = NULL WHERE id = ?");
                $update->execute([$status, $error, $job['id']]);
            }

            $countStmt = $pdo->prepare("SELECT COUNT(*) AS tot, SUM(status='sent') AS sent, SUM(status='failed') AS failed FROM bulk_optin_emails WHERE job_id = ?");
            $countStmt->execute([$job['job_id']]);
            $count = $countStmt->fetch(PDO::FETCH_ASSOC);
            $newState = 'sending';
            if ($count['sent'] == $count['tot'] && $count['tot'] > 0) {
                $newState = 'completed';
            } elseif ($count['failed'] > 0 && ($count['sent'] + $count['failed']) == $count['tot']) {
                $newState = 'failed';
            }
            $updateJob = $pdo->prepare("UPDATE bulk_optin_jobs SET sent_count = ?, failed_count = ?, status = ? WHERE id = ?");
            $updateJob->execute([(int)$count['sent'], (int)$count['failed'], $newState, $job['job_id']]);

            usleep($sleepUsec);
        }
    } catch (Throwable $e) {
        error_log('process_bulk_optin_queue error: ' . $e->getMessage());
        flock($fp, LOCK_UN);
        fclose($fp);
        return ['ok' => false, 'message' => $e->getMessage()];
    }

    flock($fp, LOCK_UN);
    fclose($fp);
    return ['ok' => true, 'message' => 'Worker completed.'];
}
}

