if (!function_exists('ensure_daily_visitors_table')) {
function ensure_daily_visitors_table() {
    static $checked = false;
    if ($checked) {
        return;
    }
    $checked = true;
    try {
        query("CREATE TABLE IF NOT EXISTS daily_visitors (
            visit_date DATE NOT NULL PRIMARY KEY,
            visits INT UNSIGNED NOT NULL DEFAULT 0,
            updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    } catch (Exception $e) {
        error_log('[ANALYTICS] ensure_daily_visitors_table: ' . $e->getMessage());
    }
}
} // end guard: ensure_daily_visitors_table


if (!function_exists('track_page_visit')) {
