    ensure_daily_visitors_table();
    try {
        query("INSERT INTO daily_visitors (visit_date, visits) VALUES (CURRENT_DATE, 1) ON DUPLICATE KEY UPDATE visits = visits + 1");
    } catch (Exception $e) {
        // Silently fail if analytics tracking fails
    }
}
} // end guard: track_page_visit


// Get user's followed users IDs
if (!function_exists('get_followed_user_ids')) {
function get_followed_user_ids($user_id) {
    if (!$user_id) return [];
    $stmt = query("SELECT following_id FROM followers WHERE follower_id = ?", [$user_id]);
    $results = $stmt->fetchAll();
    return array_map(function($row) { return $row['following_id']; }, $results);
}
} // end guard: get_followed_user_ids


// Get user's favorite tags (tags they've interacted with via likes)
if (!function_exists('get_user_favorite_tags')) {
function get_user_favorite_tags($user_id, $limit = 10) {
    if (!$user_id) return [];
    $stmt = query("
        SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(p.content, '#', numbers.n), '#', -1) as tag,
               COUNT(*) as tag_count
        FROM (SELECT 1 AS n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5) numbers
        JOIN posts p ON (LENGTH(p.content) - LENGTH(REPLACE(p.content, '#', '')) >= numbers.n)
        JOIN likes l ON l.post_id = p.id
        WHERE l.user_id = ? AND p.parent_id IS NULL
        GROUP BY tag
        ORDER BY tag_count DESC
        LIMIT ?
    ", [$user_id, $limit]);
    $results = $stmt->fetchAll();
    return array_map(function($row) { return trim(preg_replace('/[^\p{L}\p{N}_-]/u', '', $row['tag'])); }, $results);
}
} // end guard: get_user_favorite_tags


// Get user's interaction count (likes + comments)
if (!function_exists('get_user_engagement_level')) {
function get_user_engagement_level($user_id) {
    if (!$user_id) return 0;
    $stmt = query("
        SELECT 
            (SELECT COUNT(*) FROM likes WHERE user_id = ?) as likes_count
            + (SELECT COUNT(*) FROM posts WHERE user_id = ? AND parent_id IS NOT NULL AND deleted_at IS NULL) as comments_count
        as total_engagement
    ", [$user_id, $user_id]);
    $result = $stmt->fetch();
    return $result['total_engagement'] ?? 0;
}
} // end guard: get_user_engagement_level


// Get similar users based on tag interests
if (!function_exists('get_similar_users')) {
function get_similar_users($user_id, $limit = 5) {
    if (!$user_id) return [];
    $stmt = query("
        SELECT u.id, u.username, 
               COUNT(DISTINCT l1.post_id) as common_likes
        FROM users u
        JOIN likes l1 ON u.id = l1.user_id
        JOIN likes l2 ON l1.post_id = l2.post_id AND l2.user_id = ?
        WHERE u.id != ? AND u.deleted_at IS NULL
        GROUP BY u.id
        ORDER BY common_likes DESC
        LIMIT ?
    ", [$user_id, $user_id, $limit]);
    return $stmt->fetchAll();
}
} // end guard: get_similar_users


// Get relevant posts for user (personalized feed)
// Uses relevance scoring based on: followed users, favorite tags, engagement, recency, popularity
if (!function_exists('get_relevant_posts')) {
function get_relevant_posts($user_id = null, $limit = 40, $after = null) {
    $posts = [];
    
    if (!$user_id) {
        // For anonymous users, return recent popular posts
        $cursor_condition = $after ? "AND p.id < ?" : "";
        $cursor_param = $after ? [$after, $limit + 1] : [$limit + 1];
        
        try {
            $stmt = query("
                SELECT p.*, u.username, u.is_premium,
                    (SELECT COUNT(*) FROM likes WHERE post_id = p.id) as like_count,
                    (SELECT COUNT(*) FROM posts WHERE parent_id = p.id AND deleted_at IS NULL) as comment_count,
                    0 as user_has_liked
                FROM posts p
                JOIN users u ON p.user_id = u.id
                WHERE p.parent_id IS NULL AND p.deleted_at IS NULL AND u.deleted_at IS NULL
                  AND (p.scheduled_at IS NULL OR p.scheduled_at <= NOW())
                  AND (u.is_approved = 1
                       OR (u.role = 'rookie' AND (
                            SELECT COUNT(*) FROM posts p2 WHERE p2.user_id = u.id AND p2.parent_id IS NULL AND p2.deleted_at IS NULL AND p2.id <= p.id
                       ) <= 10)) $cursor_condition
                ORDER BY p.created_at DESC
                LIMIT ?
            ", array_merge($cursor_param));
        } catch (PDOException $e) {
            // Fallback for older schemas without scheduled_at column
            if (strpos($e->getMessage(), 'scheduled_at') !== false) {
                $stmt = query("
                    SELECT p.*, u.username, u.is_premium,
                        (SELECT COUNT(*) FROM likes WHERE post_id = p.id) as like_count,
                        (SELECT COUNT(*) FROM posts WHERE parent_id = p.id AND deleted_at IS NULL) as comment_count,
                        0 as user_has_liked
                    FROM posts p
                    JOIN users u ON p.user_id = u.id
                    WHERE p.parent_id IS NULL AND p.deleted_at IS NULL AND u.deleted_at IS NULL
                      AND (u.is_approved = 1
                           OR (u.role = 'rookie' AND (
                                SELECT COUNT(*) FROM posts p2 WHERE p2.user_id = u.id AND p2.parent_id IS NULL AND p2.deleted_at IS NULL AND p2.id <= p.id
                           ) <= 10)) $cursor_condition
                    ORDER BY p.created_at DESC
                    LIMIT ?
                ", array_merge($cursor_param));
            } else {
                throw $e;
            }
        }

        return $stmt->fetchAll();
    }
    
    // Get user's followed users
    $followed_ids = get_followed_user_ids($user_id);
    // Parameterized IN clause (avoid raw interpolation — SQLi fix)
    if (!empty($followed_ids)) {
        $followed_ids = array_map('intval', $followed_ids);
        $followed_ph = implode(',', array_fill(0, count($followed_ids), '?'));
        $followed_params = array_values($followed_ids);
    } else {
        $followed_ph = '0';
        $followed_params = [];
    }
    
    // Get user's favorite tags
    $favorite_tags = get_user_favorite_tags($user_id, 5);
    
    // Build cursor condition
    $cursor_condition = $after ? "AND p.id < ?" : "";
    $cursor_param = $after ? [$after] : [];
    
    // Parameterized LIKE conditions for tags (avoid addslashes — SQLi fix)
    $tag_conditions = "";
    $tag_params = [];
    if (count($favorite_tags) > 0) {
        $tag_likes = array_map(function($t) { return "p.content LIKE ?"; }, $favorite_tags);
        $tag_params = array_map(function($t) { return '%#' . $t . '%'; }, $favorite_tags);
        $tag_conditions = " OR (" . implode(" OR ", $tag_likes) . ")";
    }
    
    // Fetch paginated results with relevance scoring
    try {
        $stmt = query("
            SELECT 
                p.*, 
                u.username, 
                u.is_premium,
                (SELECT COUNT(*) FROM likes WHERE post_id = p.id) as like_count,
                (SELECT COUNT(*) FROM likes WHERE post_id = p.id AND user_id = ?) as user_has_liked,
                (SELECT COUNT(*) FROM posts WHERE parent_id = p.id AND deleted_at IS NULL) as comment_count,
                (
                    CASE WHEN p.user_id = ? THEN 200 ELSE 0 END
                    + CASE WHEN p.user_id IN ($followed_ph) THEN 100 ELSE 0 END
                    + CASE WHEN p.content LIKE '%#%' $tag_conditions THEN 50 ELSE 0 END
                    + ((SELECT COUNT(*) FROM likes WHERE post_id = p.id) * 0.5)
                    + ((SELECT COUNT(*) FROM posts WHERE parent_id = p.id AND deleted_at IS NULL) * 1.0)
                    + GREATEST(0, 75 - TIMESTAMPDIFF(HOUR, p.created_at, NOW()) * 3)
                    + (DATEDIFF(NOW(), p.created_at) * -2)
                ) as relevance_score
            FROM posts p
            JOIN users u ON p.user_id = u.id
            WHERE p.parent_id IS NULL AND p.deleted_at IS NULL AND u.deleted_at IS NULL
                AND (p.scheduled_at IS NULL OR p.scheduled_at <= NOW() OR p.user_id = ?)
                AND (u.is_approved = 1 OR u.id = ?
                     OR (u.role = 'rookie' AND (
                            SELECT COUNT(*) FROM posts p2 WHERE p2.user_id = u.id AND p2.parent_id IS NULL AND p2.deleted_at IS NULL AND p2.id <= p.id
                        ) <= 10))
            $cursor_condition
            ORDER BY relevance_score DESC, p.created_at DESC
            LIMIT ?
        ", array_merge([$user_id, $user_id], $followed_params, $tag_params, [$user_id, $user_id], $cursor_param, [$limit + 1]));
    } catch (PDOException $e) {
        // Fallback for older schemas without scheduled_at column
        if (strpos($e->getMessage(), 'scheduled_at') !== false) {
            $stmt = query("
                SELECT 
                    p.*, 
                    u.username, 
                    u.is_premium,
                    (SELECT COUNT(*) FROM likes WHERE post_id = p.id) as like_count,
                    (SELECT COUNT(*) FROM likes WHERE post_id = p.id AND user_id = ?) as user_has_liked,
                    (SELECT COUNT(*) FROM posts WHERE parent_id = p.id AND deleted_at IS NULL) as comment_count,
                    (
                        CASE WHEN p.user_id = ? THEN 200 ELSE 0 END
                        + CASE WHEN p.user_id IN ($followed_ph) THEN 100 ELSE 0 END
                        + CASE WHEN p.content LIKE '%#%' $tag_conditions THEN 50 ELSE 0 END
                        + ((SELECT COUNT(*) FROM likes WHERE post_id = p.id) * 0.5)
                        + ((SELECT COUNT(*) FROM posts WHERE parent_id = p.id AND deleted_at IS NULL) * 1.0)
                        + GREATEST(0, 75 - TIMESTAMPDIFF(HOUR, p.created_at, NOW()) * 3)
                        + (DATEDIFF(NOW(), p.created_at) * -2)
                    ) as relevance_score
                FROM posts p
                JOIN users u ON p.user_id = u.id
                WHERE p.parent_id IS NULL AND p.deleted_at IS NULL AND u.deleted_at IS NULL
                    AND (u.is_approved = 1 OR u.id = ?
                         OR (u.role = 'rookie' AND (
                                SELECT COUNT(*) FROM posts p2 WHERE p2.user_id = u.id AND p2.parent_id IS NULL AND p2.deleted_at IS NULL AND p2.id <= p.id
                            ) <= 10))
                $cursor_condition
                ORDER BY relevance_score DESC, p.created_at DESC
                LIMIT ?
            ", array_merge([$user_id, $user_id], $followed_params, $tag_params, [$user_id], $cursor_param, [$limit + 1]));
        } else {
            throw $e;
        }
    }

    return $stmt->fetchAll();
}
} // end guard: get_relevant_posts


// Get pagination info for relevant posts
if (!function_exists('get_relevant_posts_paginated')) {
function get_relevant_posts_paginated($user_id = null, $limit = 40, $after = null) {
    $all_posts = get_relevant_posts($user_id, $limit, $after);
    
    $has_next = false;
    $posts = [];
    
    if (count($all_posts) > $limit) {
        array_pop($all_posts);
        $has_next = true;
    }
    
    $posts = $all_posts;
    // Batch-load polls and tests (avoids N+1 per-post queries)
    $post_ids = array_column($posts, 'id');
    $polls_map  = function_exists('batch_get_polls_for_posts')  ? batch_get_polls_for_posts($post_ids)  : [];
    $tests_map  = function_exists('batch_get_tests_for_posts')  ? batch_get_tests_for_posts($post_ids)  : [];
    $cc_map     = function_exists('batch_get_recursive_comment_counts') ? batch_get_recursive_comment_counts($post_ids) : [];
    $images_map = function_exists('batch_get_images_for_posts') ? batch_get_images_for_posts($post_ids) : [];
    foreach ($posts as &$ppp) {
        $ppp['poll']  = $polls_map[$ppp['id']]  ?? null;
        $ppp['test']  = $tests_map[$ppp['id']]  ?? null;
        $ppp['image'] = $images_map[$ppp['id']] ?? null;
        if (isset($cc_map[$ppp['id']])) { $ppp['comment_count'] = $cc_map[$ppp['id']]; }
    }
    unset($ppp);

    return [
        'posts' => $posts,
        'has_next' => $has_next,
        'first_id' => count($posts) > 0 ? $posts[0]['id'] : null,
        'last_id' => count($posts) > 0 ? $posts[count($posts) - 1]['id'] : null
    ];
}
} // end guard: get_relevant_posts_paginated


// Follow a user
if (!function_exists('follow_user')) {
function follow_user($follower_id, $following_id) {
    if ($follower_id == $following_id) return false; // Can't follow yourself
    if (!$follower_id || !$following_id) return false;
    
    try {
        query("INSERT IGNORE INTO followers (follower_id, following_id) VALUES (?, ?)", [$follower_id, $following_id]);
        return true;
    } catch (Exception $e) {
        return false;
    }
}
} // end guard: follow_user


