if (!function_exists('favorites_table_exists')) {
function favorites_table_exists(): bool {
    static $result = null;
    if ($result !== null) {
        return $result;
    }
    try {
        $pdo = db_connect();
        $pdo->exec("CREATE TABLE IF NOT EXISTS `favorites` (
            `id`         INT UNSIGNED NOT NULL AUTO_INCREMENT,
            `user_id`    INT UNSIGNED NOT NULL,
            `post_id`    INT UNSIGNED NOT NULL,
            `created_at` DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (`id`),
            UNIQUE KEY `uq_favorites_user_post` (`user_id`, `post_id`),
            KEY `idx_favorites_user` (`user_id`),
            KEY `idx_favorites_post` (`post_id`)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $result = true;
    } catch (Throwable $e) {
        error_log('favorites_table_exists error: ' . $e->getMessage());
        $result = false;
    }
    return $result;
}
}

