        return false;
    }
    try {
        $stmt = query(
            "SELECT 1 FROM favorites WHERE user_id = ? AND post_id = ? LIMIT 1",
            [$user_id, $post_id]
        );
        return (bool) $stmt->fetch();
    } catch (Throwable $e) {
        error_log('user_has_favorited_post error: ' . $e->getMessage());
        return false;
    }
}
}

if (!function_exists('toggle_favorite')) {
function toggle_favorite(int $user_id, int $post_id): bool {
    $pdo = db_connect();
    try {
        $pdo->beginTransaction();

        $stmt = $pdo->prepare("SELECT id FROM favorites WHERE user_id = ? AND post_id = ? FOR UPDATE");
        $stmt->execute([$user_id, $post_id]);
        $existing = $stmt->fetch(PDO::FETCH_ASSOC);

        if ($existing) {
            query("DELETE FROM favorites WHERE user_id = ? AND post_id = ?", [$user_id, $post_id]);
            $pdo->commit();
            return false; // removed
        }

        query(
            "INSERT INTO favorites (user_id, post_id) VALUES (?, ?) ON DUPLICATE KEY UPDATE created_at = created_at",
            [$user_id, $post_id]
        );
        $pdo->commit();
        return true; // added
    } catch (Throwable $e) {
        if ($pdo->inTransaction()) {
            $pdo->rollBack();
        }
        error_log('toggle_favorite error: ' . $e->getMessage());
        return false;
    }
}
}
